void check(bool b,const char*m){if(!b)throw std::runtime_error(m);}
class Original:public H8SEmulator {public:int rh()const{return lastread;}int wh()const{return lastwrite;}void histories(int a,int b){lastread=a;lastwrite=b;}int depth()const{return indent;}void depth(int n){indent=n;}};
uint32_t seed=0x2cf41c91;uint32_t rnd(){seed^=seed<<13;seed^=seed>>17;return seed^=seed<<5;}
struct Event {uint64_t time;uint32_t pc,sp,at,r0,r1,r6;uint8_t ccr,value;bool write;};
template<class C>struct Bus:H8SDevice {C&c;std::array<Event,128>events{};unsigned n=0,group=0;bool liveStatus=false;explicit Bus(C&x):c(x){}void record(uint32_t at,uint8_t v,bool w){check(n<events.size(),"bus overflow");events[n++]={c.cycles,uint32_t(c.getPC()),c.getSP(),at,uint32_t(c.reg32(0)),uint32_t(c.reg32(1)),uint32_t(c.reg32(6)),c.ccr,v,w};}uint8_t read(uint32_t at)override{auto v=at==0x600004&&!liveStatus?uint8_t(group==1?16:7):c.memory[at];record(at,v,false);return v;}void write(uint32_t at,uint8_t v)override{record(at,v,true);c.memory[at]=v;if(at==0x600000&&v==8)group=1;if(at==0x60000e)group=2;}};
struct F{std::unique_ptr<Original>a=std::make_unique<Original>();std::unique_ptr<kstation::Stage1Cpu>b=std::make_unique<kstation::Stage1Cpu>();Bus<Original>x{*a};Bus<kstation::Stage1Cpu>y{*b};uint64_t graphs=0,phases=0,events=0,children=0,handlerCalls=0,activityCalls=0;uint32_t stack=0xffff00;
 explicit F(const std::vector<uint8_t>&r){a->loadmem(r.data(),unsigned(r.size()),0);b->loadmem(r.data(),unsigned(r.size()),0);for(auto q:std::array<std::pair<uint32_t,uint32_t>,8>{{{0xbfa0,0x1000},{0xc9b6,0x200},{0xcbb6,0x24a},{0xd000,0x1400},{0xfffd20,0x210},{0xffff00,0x80},{0xffffd0,4},{0x600000,16}}}){a->memmap(&x,q.first,q.second);b->memmap(&y,q.first,q.second);}}
 void byte(uint32_t p,uint8_t v){a->memory[p&0xffffff]=b->memory[p&0xffffff]=v;}void word(uint32_t p,uint16_t v){byte(p,v>>8);byte(p+1,v);}void wide(uint32_t p,uint32_t v){word(p,v>>16);word(p+2,v);}
 void prep(uint32_t pc,uint8_t flags){for(unsigned i=0;i<8;++i)a->regs[i].er=b->regs[i].er=int32_t(rnd());a->pc=a->makepc(pc);b->pc=b->makepc(pc);a->setSP(stack);b->setSP(stack);wide(stack,0x7000);a->ccr=b->ccr=flags;a->exr=b->exr=uint8_t(rnd());a->cycles=b->cycles=rnd();a->histories(0x20000,0x30000);b->histories(0x20000,0x30000);a->depth(2);b->irqDepth(2);a->pending_irqs=b->pending_irqs=0;a->pending_irqs_high=b->pending_irqs_high=0;a->interruptMode2=b->interruptMode2=false;x.n=y.n=0;x.group=y.group=0;}
 void equal(){bool ok=a->getPC()==b->getPC()&&a->cycles==b->cycles&&a->ccr==b->ccr&&a->exr==b->exr&&a->getSP()==b->getSP()&&a->rh()==b->readHistory()&&a->wh()==b->writeHistory()&&a->depth()==b->irqDepth();for(unsigned i=0;i<8;++i)ok&=a->regs[i].er==b->regs[i].er;if(!ok){std::fprintf(stderr,"PC=%x/%x cycles=%llu/%llu CCR=%x/%x SP=%x/%x R0=%x/%x R1=%x/%x R6=%x/%x history=%x/%x %x/%x\n",a->getPC(),b->getPC(),a->cycles,b->cycles,a->ccr,b->ccr,a->getSP(),b->getSP(),unsigned(a->reg32(0)),unsigned(b->reg32(0)),unsigned(a->reg32(1)),unsigned(b->reg32(1)),unsigned(a->reg32(6)),unsigned(b->reg32(6)),a->rh(),b->readHistory(),a->wh(),b->writeHistory());throw std::runtime_error("frame mismatch");}check(x.n==y.n,"bus count");for(unsigned i=0;i<x.n;++i){auto&p=x.events[i];auto&q=y.events[i];if(!(p.time==q.time&&p.pc==q.pc&&p.sp==q.sp&&p.at==q.at&&p.r0==q.r0&&p.r1==q.r1&&p.r6==q.r6&&p.ccr==q.ccr&&p.value==q.value&&p.write==q.write)){std::fprintf(stderr,"bus at %x/%x, pc %x/%x ccr %x/%x time %llu/%llu\n",p.at,q.at,p.pc,q.pc,p.ccr,q.ccr,p.time,q.time);throw std::runtime_error("bus differs");}}events+=x.n;x.n=y.n=0;for(auto q:std::array<std::pair<uint32_t,uint32_t>,3>{{{0xc9b6,0x200},{0xfffd20,0x210},{0xfffef0,0x20}}})check(!std::memcmp(a->memory+q.first,b->memory+q.first,q.second),"RAM mismatch");}
 void oracle(){a->step();b->step();equal();}
 void reset(uint8_t flags,uint8_t mode){prep(0x2f80,flags);byte(0xcd0e,mode);kstation::NativeMidiSysExReset t;unsigned n=0;while(!t.task().complete()){check(++n<10,"reset hang");check(t.step(*b),"reset phase");a->step();equal();check(!std::memcmp(a->memory+0xcc06,b->memory+0xcc06,8),"reset state mismatch");check(a->memory[0xcd0e]==b->memory[0xcd0e],"reset mode mismatch");++phases;}++graphs;}
 void reply(uint8_t flags,uint8_t pattern,bool patch,uint8_t section,uint8_t index){using T=kstation::MidiSysExDumpBankReplyTask;prep(patch?0x332c:0x334a,flags);a->reg8(13)=b->reg8(13)=int8_t(pattern);a->reg8(6)=b->reg8(6)=int8_t(section);a->reg8(14)=b->reg8(14)=int8_t(index);uint32_t source=0x226400+uint32_t(section-1)*0x3200+uint32_t(index)*0x80;for(unsigned i=0;i<256;++i)byte(source+i,uint8_t(pattern+i*29));kstation::NativeMidiSysExDumpBankReply t(patch?T::Kind::Patch:T::Kind::Performance,0x7000);unsigned n=0,outputs=0;auto sendBytes=[&](uint32_t source,uint16_t count){kstation::NativeMidiSysExSendBytes send(source,count);while(!send.task().complete()){if(send.task().awaitingChild()){check(uint32_t(a->getPC())==0xbb4,"dump uart");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);check(send.resumeChild(*b),"dump send resume");++outputs;++children;}else{check(send.step(*b),"dump send phase");a->step();equal();++phases;}}};while(!t.task().complete()){check(++n<100,"dump hang");if(t.task().awaitingChild()){auto ch=t.task().child();if(ch==T::Child::Address){kstation::NativeMidiSysExDumpAddress addr(pattern,section,index);while(!addr.task().complete()){if(addr.task().awaitingChild()){kstation::NativeMidiSysExIdentity id;while(!id.task().complete()){check(id.step(*b),"reply identity");a->step();equal();++phases;}check(addr.resumeChild(*b),"reply address resume");}else{check(addr.step(*b),"reply address");a->step();equal();++phases;}}}else if(ch==T::Child::Header){kstation::NativeMidiSysExSendHeader h;while(!h.task().complete()){if(h.task().awaitingChild()){if(h.task().child()==kstation::MidiSysExSendHeaderTask::Child::SendIdentity)sendBytes(0xcd1a,12);else{auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);++outputs;}check(h.resumeChild(*b),"dump header resume");++children;}else{check(h.step(*b),"dump header phase");a->step();equal();++phases;}}}else if(ch==T::Child::SendData)sendBytes(source,patch?0x80:0x100);else{uint32_t at=0xbb4;check(uint32_t(a->getPC())==at,"dump child");auto x=a->memory[at],y=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,x);byte(at+1,y);++outputs;}check(t.resumeChild(*b),"dump resume");++children;continue;}check(t.step(*b),"dump phase");a->step();equal();++phases;}check(outputs==(patch?142u:270u),"dump bytes");check(a->memory[0xcd20]==b->memory[0xcd20],"dump type");++graphs;}
 void system(uint8_t flags,uint8_t pattern){using T=kstation::MidiSysExDumpSystemTask;prep(0x3306,flags);for(unsigned i=0;i<256;++i)byte(0x21ff00+i,uint8_t(pattern+i*29));kstation::NativeMidiSysExDumpSystem t;unsigned n=0,outputs=0;auto sendBytes=[&](uint32_t source,uint16_t count){kstation::NativeMidiSysExSendBytes send(source,count);while(!send.task().complete()){if(send.task().awaitingChild()){check(uint32_t(a->getPC())==0xbb4,"dump uart");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);check(send.resumeChild(*b),"dump send resume");++outputs;++children;}else{check(send.step(*b),"dump send phase");a->step();equal();++phases;}}};while(!t.task().complete()){check(++n<100,"dump hang");if(t.task().awaitingChild()){auto ch=t.task().child();if(ch==T::Child::Identity){kstation::NativeMidiSysExIdentity id;while(!id.task().complete()){check(id.step(*b),"dump identity");a->step();equal();++phases;}}else if(ch==T::Child::Header){kstation::NativeMidiSysExSendHeader h;while(!h.task().complete()){if(h.task().awaitingChild()){if(h.task().child()==kstation::MidiSysExSendHeaderTask::Child::SendIdentity)sendBytes(0xcd1a,12);else{auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);++outputs;}check(h.resumeChild(*b),"dump header resume");++children;}else{check(h.step(*b),"dump header phase");a->step();equal();++phases;}}}else if(ch==T::Child::SendData)sendBytes(0x21ff00,0x100);else{uint32_t at=0xbb4;check(uint32_t(a->getPC())==at,"dump child");auto x=a->memory[at],y=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,x);byte(at+1,y);++outputs;}check(t.resumeChild(*b),"dump resume");++children;continue;}check(t.step(*b),"dump phase");a->step();equal();++phases;}check(outputs==270,"dump bytes");check(a->memory[0xcd20]==b->memory[0xcd20],"dump type");++graphs;}
 void dump(uint8_t flags,uint8_t pattern){using T=kstation::MidiSysExDumpCurrentTask;prep(0x3256,flags);for(unsigned i=0;i<128;++i)byte(0xba5c+i,uint8_t(pattern+i*29));kstation::NativeMidiSysExDumpCurrent t;unsigned n=0,outputs=0;auto sendBytes=[&](uint32_t source,uint16_t count){kstation::NativeMidiSysExSendBytes send(source,count);while(!send.task().complete()){if(send.task().awaitingChild()){check(uint32_t(a->getPC())==0xbb4,"dump uart");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);check(send.resumeChild(*b),"dump send resume");++outputs;++children;}else{check(send.step(*b),"dump send phase");a->step();equal();++phases;}}};while(!t.task().complete()){check(++n<100,"dump hang");if(t.task().awaitingChild()){auto ch=t.task().child();if(ch==T::Child::Identity){kstation::NativeMidiSysExIdentity id;while(!id.task().complete()){check(id.step(*b),"dump identity");a->step();equal();++phases;}}else if(ch==T::Child::Header){kstation::NativeMidiSysExSendHeader h;while(!h.task().complete()){if(h.task().awaitingChild()){if(h.task().child()==kstation::MidiSysExSendHeaderTask::Child::SendIdentity)sendBytes(0xcd1a,12);else{auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);++outputs;}check(h.resumeChild(*b),"dump header resume");++children;}else{check(h.step(*b),"dump header phase");a->step();equal();++phases;}}}else if(ch==T::Child::SendData)sendBytes(0xba5c,0x80);else{uint32_t at=ch==T::Child::Refresh?0x525c:0xbb4;check(uint32_t(a->getPC())==at,"dump child");auto x=a->memory[at],y=a->memory[at+1];byte(at,0x54);byte(at+1,0x70);oracle();byte(at,x);byte(at+1,y);if(ch==T::Child::SendEnd)++outputs;}check(t.resumeChild(*b),"dump resume");++children;continue;}check(t.step(*b),"dump phase");a->step();equal();++phases;}check(outputs==142,"dump bytes");check(a->memory[0xcd20]==b->memory[0xcd20],"dump type");++graphs;}
 void header(uint8_t flags,uint8_t pattern){using T=kstation::MidiSysExSendHeaderTask;prep(0x3242,flags);for(unsigned i=0;i<12;++i)byte(0xcd1a+i,uint8_t(pattern+i*29));kstation::NativeMidiSysExSendHeader t;unsigned n=0,outputs=0;while(!t.task().complete()){check(++n<100,"send header hang");if(t.task().awaitingChild()){if(t.task().child()==T::Child::SendStart){check(uint8_t(a->reg8(0))==0xf0,"start byte");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);++outputs;}else{kstation::NativeMidiSysExSendBytes data(0xcd1a,12);while(!data.task().complete()){if(data.task().awaitingChild()){check(uint8_t(a->reg8(0))==uint8_t((pattern+(outputs-1)*29)&127),"header byte");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);check(data.resumeChild(*b),"header data resume");++outputs;++children;}else{check(data.step(*b),"header data phase");a->step();equal();++phases;}}}check(t.resumeChild(*b),"header child resume");++children;continue;}check(t.step(*b),"header send phase");a->step();equal();++phases;}check(outputs==13,"header byte count");++graphs;}
 void send(uint8_t flags,uint32_t source,uint16_t count){prep(0x3234,flags);a->reg32(6)=b->reg32(6)=int32_t(source);a->reg16(5)=b->reg16(5)=int16_t(count);for(unsigned i=0;i<65536;++i)byte(source+i,uint8_t(i*29+flags));kstation::NativeMidiSysExSendBytes t(source,count);unsigned n=0,outputs=0;while(!t.task().complete()){check(++n<400000,"send hang");if(t.task().awaitingChild()){check(uint32_t(a->getPC())==0xbb4,"send child");check(uint8_t(a->reg8(0))==uint8_t((outputs*29+flags)&127),"send byte");auto x=a->memory[0xbb4],y=a->memory[0xbb5];byte(0xbb4,0x54);byte(0xbb5,0x70);oracle();byte(0xbb4,x);byte(0xbb5,y);check(t.resumeChild(*b),"send resume");++outputs;++children;continue;}check(t.step(*b),"send phase");a->step();equal();++phases;}check(outputs==(count?count:65536),"send count");++graphs;}
};
