int main(int argc,char**argv){try{if(argc<2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>rom{std::istreambuf_iterator<char>(in),{}};check(rom.size()==49728,"ROM size");F f(rom);for(unsigned flags=0;flags<256;++flags)for(bool patch:{false,true})for(uint8_t section:{uint8_t(1),uint8_t(4)})for(uint8_t index:{uint8_t(0),uint8_t(98)})f.reply(uint8_t(flags),uint8_t(flags^index),patch,section,index);for(unsigned flags=0;flags<256;++flags)for(uint8_t p:{uint8_t(0),uint8_t(1),uint8_t(127),uint8_t(255)})f.system(uint8_t(flags),p);for(unsigned flags=0;flags<256;++flags)for(uint8_t p:{uint8_t(0),uint8_t(1),uint8_t(127),uint8_t(255)})f.dump(uint8_t(flags),p);for(unsigned flags=0;flags<256;++flags)for(uint8_t p:{uint8_t(0),uint8_t(1),uint8_t(127),uint8_t(255)})f.header(uint8_t(flags),p);for(unsigned flags=0;flags<256;++flags)for(uint16_t count:{uint16_t(1),uint16_t(2),uint16_t(12),uint16_t(256)})f.send(uint8_t(flags),0x100000,count);f.send(0,0x100000,0);std::printf("{\"passed\":true,\"graphs\":%llu,\"native_phases\":%llu,\"ordered_bus_events\":%llu,\"explicit_children\":%llu}\n",(unsigned long long)f.graphs,(unsigned long long)f.phases,(unsigned long long)f.events,(unsigned long long)f.children);return 0;}catch(const std::exception&e){std::fprintf(stderr,"FAIL: %s\n",e.what());return 1;}}
